3	import (
4		"archive/tar"
5		"bytes"
6		"compress/gzip"
7		"crypto/sha256"
8		"encoding/hex"
9		"encoding/json"
10		"errors"
11		"fmt"
12		"os"
13		"path/filepath"
14		"strings"
15		"time"
16	)
17	
18	// layerGzip is the H-LAYER fallback switch. false writes the layer as a plain tar
19	// (application/vnd.oci.image.layer.v1.tar); true compresses it with gzip
20	// (application/vnd.oci.image.layer.v1.tar+gzip), for a Nexus that refuses an
21	// uncompressed layer. Nothing else changes: the diff id stays the digest of the
22	// tar. With gzip the digests depend on the compress/gzip output of the Go version,
23	// so the golden has to be regenerated with a Go upgrade.
24	const layerGzip = false
25	
26	const (
27		mediaTypeManifest  = "application/vnd.oci.image.manifest.v1+json"
28		mediaTypeConfig    = "application/vnd.oci.image.config.v1+json"
29		mediaTypeLayerTar  = "application/vnd.oci.image.layer.v1.tar"
30		mediaTypeLayerGzip = "application/vnd.oci.image.layer.v1.tar+gzip"
31	
32		annotationRefName = "org.opencontainers.image.ref.name"
33		labelSource       = "org.devdesk.nexus-bench.source"
34	
35		layoutVersion = "1.0.0"
36		layerFileMode = 0o644
37		layerDirMode  = 0o755
38	)
39	
40	// ociDescriptorJSON is an OCI content descriptor.
41	type ociDescriptorJSON struct {
42		MediaType   string            `json:"mediaType"`
43		Digest      string            `json:"digest"`
44		Size        int64             `json:"size"`
45		Annotations map[string]string `json:"annotations,omitempty"`
46	}
47	
48	type ociManifestJSON struct {
49		SchemaVersion int                 `json:"schemaVersion"`
50		MediaType     string              `json:"mediaType"`
51		Config        ociDescriptorJSON   `json:"config"`
52		Layers        []ociDescriptorJSON `json:"layers"`
53	}
54	
55	type ociIndexJSON struct {
56		SchemaVersion int                 `json:"schemaVersion"`
57		MediaType     string              `json:"mediaType"`
58		Manifests     []ociDescriptorJSON `json:"manifests"`
59	}
60	
61	// ociImageConfigJSON is the image configuration. It has no "created" key: a date
62	// would make the digest depend on the clock.
63	type ociImageConfigJSON struct {
64		Architecture string `json:"architecture"`
65		OS           string `json:"os"`
66		Config       struct {
67			Labels map[string]string `json:"labels"`
68		} `json:"config"`
69		RootFS struct {
70			Type    string   `json:"type"`
71			DiffIDs []string `json:"diff_ids"`
72		} `json:"rootfs"`
73	}
74	
75	// builtImage is an image with every blob it needs, in memory.
76	type builtImage struct {
77		manifest ociDescriptorJSON
78		blobs    []blob // manifest, config, layer
79	}
80	
81	type blob struct {
82		digest string
83		data   []byte
84	}
85	
86	// WriteLayout writes an OCI image layout holding every image of images under dir
87	// (which must exist and be empty) and returns the reference name of each image in
88	// the layout, in the same order. The bytes depend on the images alone.
89	func WriteLayout(dir string, images []DatasetImage) (refs []string, err error) {
90		if err := requireEmptyDir(dir); err != nil {
91			return nil, err
92		}
93		// Build everything first: a failure writes nothing.
94		index := ociIndexJSON{SchemaVersion: 2, MediaType: "application/vnd.oci.image.index.v1+json"}
95		var blobs []blob
96		for i, img := range images {
97			built, err := buildImage(img)
98			if err != nil {
99				return nil, fmt.Errorf("build %s:%s: %w", img.Name, img.Tag, err)
100			}
101			ref := fmt.Sprintf("img-%02d", i+1)
102			desc := built.manifest
103			desc.Annotations = map[string]string{annotationRefName: ref}
104			index.Manifests = append(index.Manifests, desc)
105			blobs = append(blobs, built.blobs...)
106			refs = append(refs, ref)
107		}
108		indexJSON, err := json.Marshal(index)
109		if err != nil {
110			return nil, fmt.Errorf("encode index.json: %w", err)
111		}
112	
113		if err := writeLayoutFiles(dir, blobs, indexJSON); err != nil {
114			return nil, err
115		}
116		return refs, nil
117	}
118	
119	// imageDigest returns the manifest digest of img, computed without writing anything.
120	func imageDigest(img DatasetImage) string {
121		built, err := buildImage(img)
122		if err != nil {
123			// Only an unmarshalable value or a tar header refusal can fail, none of
124			// which depends on the image: the table is fixed.
125			panic(fmt.Sprintf("nexusbench: build %s:%s: %v", img.Name, img.Tag, err))
126		}
127		return built.manifest.Digest
128	}
129	
130	func requireEmptyDir(dir string) error {
131		entries, err := os.ReadDir(dir)
132		if err != nil {
133			return fmt.Errorf("read layout directory: %w", err)
134		}
135		if len(entries) > 0 {
136			return fmt.Errorf("layout directory %s is not empty", dir)
137		}
138		return nil
139	}
140	
141	func writeLayoutFiles(dir string, blobs []blob, indexJSON []byte) error {
142		blobDir := filepath.Join(dir, "blobs", "sha256")
143		if err := os.MkdirAll(blobDir, 0o755); err != nil {
144			return fmt.Errorf("create blobs directory: %w", err)
145		}
146		for _, b := range blobs {
147			_, hexa, _ := strings.Cut(b.digest, ":")
148			if err := os.WriteFile(filepath.Join(blobDir, hexa), b.data, 0o644); err != nil {
149				return fmt.Errorf("write blob %s: %w", b.digest, err)
150			}
151		}
152		marker := []byte(`{"imageLayoutVersion":"` + layoutVersion + `"}`)
153		if err := os.WriteFile(filepath.Join(dir, "oci-layout"), marker, 0o644); err != nil {
154			return fmt.Errorf("write oci-layout: %w", err)
155		}
156		if err := os.WriteFile(filepath.Join(dir, "index.json"), indexJSON, 0o644); err != nil {
157			return fmt.Errorf("write index.json: %w", err)
158		}
159		return nil
160	}
161	
162	// sourceName is the value of the source label and the folder under /bench.
163	func sourceName(l Location) string {
164		if l == LocationHosted {
165			return "hosted"
166		}
167		return "upstream"
168	}
169	
170	// buildImage builds the one-layer image of img: manifest, config and layer.
171	func buildImage(img DatasetImage) (builtImage, error) {
172		source := sourceName(img.Location)
173		tarBytes, err := buildTar(img, source)
174		if err != nil {
175			return builtImage{}, err
176		}
177		layerBytes, layerType := tarBytes, mediaTypeLayerTar
178		if layerGzip {
179			if layerBytes, err = gzipBytes(tarBytes); err != nil {
180				return builtImage{}, err
181			}
182			layerType = mediaTypeLayerGzip
183		}
184	
185		var cfg ociImageConfigJSON
186		cfg.Architecture, cfg.OS = "amd64", "linux"
187		cfg.Config.Labels = map[string]string{labelSource: source}
188		cfg.RootFS.Type = "layers"
189		cfg.RootFS.DiffIDs = []string{digestOf(tarBytes)}
190		cfgBytes, err := json.Marshal(cfg)
191		if err != nil {
192			return builtImage{}, fmt.Errorf("encode config: %w", err)
193		}
194	
195		layer := blob{digestOf(layerBytes), layerBytes}
196		config := blob{digestOf(cfgBytes), cfgBytes}
197		manifest := ociManifestJSON{
198			SchemaVersion: 2,
199			MediaType:     mediaTypeManifest,
200			Config:        ociDescriptorJSON{MediaType: mediaTypeConfig, Digest: config.digest, Size: int64(len(config.data))},
201			Layers:        []ociDescriptorJSON{{MediaType: layerType, Digest: layer.digest, Size: int64(len(layer.data))}},
202		}
203		manifestBytes, err := json.Marshal(manifest)
204		if err != nil {
205			return builtImage{}, fmt.Errorf("encode manifest: %w", err)
206		}
207		m := blob{digestOf(manifestBytes), manifestBytes}
208		return builtImage{
209			manifest: ociDescriptorJSON{MediaType: mediaTypeManifest, Digest: m.digest, Size: int64(len(m.data))},
210			blobs:    []blob{m, config, layer},
211		}, nil
212	}
213	
214	// buildTar writes the layer: /bench/<source>/<name>-<tag>.txt and its two parent
215	// folders, sorted, without date, owner or name, with fixed modes.
216	func buildTar(img DatasetImage, source string) ([]byte, error) {
217		file := strings.ReplaceAll(img.Name, "/", "-") + "-" + img.Tag + ".txt"
218		content := fmt.Sprintf("nexus-bench data set\nsource: %s\nimage: %s:%s\n", source, img.Name, img.Tag)
219		entries := []struct {
220			name string
221			dir  bool
222			body string
223		}{
224			{name: "bench/", dir: true},
225			{name: "bench/" + source + "/", dir: true},
226			{name: "bench/" + source + "/" + file, body: content},
227		}
228	
229		var buf bytes.Buffer
230		tw := tar.NewWriter(&buf)
231		for _, e := range entries {
232			h := &tar.Header{Name: e.name, ModTime: time.Unix(0, 0), Format: tar.FormatUSTAR}
233			if e.dir {
234				h.Typeflag, h.Mode = tar.TypeDir, layerDirMode
235			} else {
236				h.Typeflag, h.Mode, h.Size = tar.TypeReg, layerFileMode, int64(len(e.body))
237			}
238			if err := tw.WriteHeader(h); err != nil {
239				return nil, fmt.Errorf("write tar header %s: %w", e.name, err)
240			}
241			if _, err := tw.Write([]byte(e.body)); err != nil {
242				return nil, fmt.Errorf("write tar entry %s: %w", e.name, err)
243			}
244		}
245		if err := tw.Close(); err != nil {
246			return nil, fmt.Errorf("close tar: %w", err)
247		}
248		return buf.Bytes(), nil
249	}
250	
251	// gzipBytes compresses data with a header that carries no name and no date.
252	func gzipBytes(data []byte) ([]byte, error) {
253		var buf bytes.Buffer
254		zw := gzip.NewWriter(&buf)
255		if _, err := zw.Write(data); err != nil {
256			return nil, errors.Join(errors.New("compress layer"), err)
257		}
258		if err := zw.Close(); err != nil {
259			return nil, errors.Join(errors.New("compress layer"), err)
260		}
261		return buf.Bytes(), nil
262	}
263	
264	func digestOf(data []byte) string {
265		sum := sha256.Sum256(data)
266		return "sha256:" + hex.EncodeToString(sum[:])
267	}
