156	// neverRan fails when the stand-in was run: the code under test had to refuse
157	// before it started a process.
158	func (h helperTool) neverRan(t *testing.T) {
159		t.Helper()
160		if rs := h.records(t); len(rs) != 0 {
161			t.Errorf("the stand-in %s was run %d time(s) (first: %q), want a refusal before any process", h.name, len(rs), rs[0].Args)
162		}
163	}
