149	func checkCopyArgs(t *testing.T, rec helperRecord, src, dst ImageRef, o CopyOptions) {
150		t.Helper()
151		args := rec.Args
152		copyAt := slices.Index(args, "copy")
153		if copyAt < 0 {
154			t.Fatalf("no copy subcommand in %q", args)
155		}
156		if len(args) < copyAt+3 || args[len(args)-2] != refArg(src) || args[len(args)-1] != refArg(dst) {
157			t.Errorf("the arguments end with %q, want the source %q then the destination %q", args[max(0, len(args)-2):], refArg(src), refArg(dst))
158		}
159		if policyAt := slices.IndexFunc(args, func(a string) bool { return a == "--policy" || strings.HasPrefix(a, "--policy=") }); policyAt < 0 || policyAt > copyAt {
160			t.Errorf("--policy must be given, before the copy subcommand: %q", args)
161		}
162		if slices.Contains(args, "--insecure-policy") {
163			t.Errorf("--insecure-policy is used, want an explicit policy file: %q", args)
164		}
165	
166		for _, side := range []struct {
167			name  string
168			ref   ImageRef
169			creds *Credentials
170		}{{"src", src, o.SrcCreds}, {"dest", dst, o.DestCreds}} {
171			tls := "--" + side.name + "-tls-verify"
172			switch {
173			case side.ref.Transport == "docker" && !slices.Contains(args, tls+"=false"):
174				t.Errorf("%s is a docker reference but %s=false is missing: %q", side.name, tls, args)
175			case side.ref.Transport != "docker" && argWithPrefix(args, tls):
176				t.Errorf("%s is %s, not a registry, but %s is given: %q", side.name, side.ref.Transport, tls, args)
177			}
178			for _, a := range args {
179				if strings.HasPrefix(a, tls) && a != tls+"=false" {
180					t.Errorf("TLS verification must only ever be switched off, got %q", a)
181				}
182			}
183			noCreds := "--" + side.name + "-no-creds"
184			if has := slices.Contains(args, noCreds); has != (side.creds == nil) {
185				t.Errorf("%s present = %v, want %v (credentials given: %v): %q", noCreds, has, side.creds == nil, side.creds != nil, args)
186			}
187		}
188		if has := slices.Contains(args, "--preserve-digests"); has != o.PreserveDigests {
189			t.Errorf("--preserve-digests present = %v, want %v: %q", has, o.PreserveDigests, args)
190		}
191	}
