197	// checkNoSecretLeak fails when a password, or a flag that carries one, shows in
198	// the arguments (visible to every account through /proc) or in the environment.
199	func checkNoSecretLeak(t *testing.T, rec helperRecord, passwords ...string) {
200		t.Helper()
201		for _, a := range rec.Args {
202			for _, pw := range passwords {
203				if strings.Contains(a, pw) {
204					t.Errorf("argument %q carries a password", a)
205				}
206			}
207			for _, banned := range []string{"--creds", "--src-creds", "--dest-creds", "--src-password", "--dest-password", "--password", "--src-username", "--dest-username", "--username", "--src-registry-token", "--dest-registry-token", "--registry-token"} {
208				if a == banned || strings.HasPrefix(a, banned+"=") {
209					t.Errorf("argument %q hands a credential to skopeo on the command line", a)
210				}
211			}
212		}
213		for _, kv := range rec.Env {
214			for _, pw := range passwords {
215				if strings.Contains(kv, pw) {
216					name, _, _ := strings.Cut(kv, "=")
217					t.Errorf("the environment variable %s carries a password", name)
218				}
219			}
220		}
