223	// checkAuthfiles checks that the credentials of a side reach skopeo through an
224	// authentication file, 0600 in a 0700 folder, and only when there are some.
225	func checkAuthfiles(t *testing.T, rec helperRecord, src, dst ImageRef, o CopyOptions) {
226		t.Helper()
227		if o.SrcCreds == nil && o.DestCreds == nil {
228			if len(rec.Authfiles) != 0 {
229				t.Errorf("an authentication file is given without credentials: %+v", rec.Authfiles)
230			}
231			return
232		}
233		for _, af := range rec.Authfiles {
234			if af.Mode != 0o600 {
235				t.Errorf("%s %s has mode %04o, want 0600", af.Flag, af.Path, af.Mode)
236			}
237			if af.DirMode != 0o700 {
238				t.Errorf("the folder of %s has mode %04o, want 0700", af.Path, af.DirMode)
239			}
240		}
241		for _, side := range []struct {
242			ref   ImageRef
243			creds *Credentials
244		}{{src, o.SrcCreds}, {dst, o.DestCreds}} {
245			if side.creds == nil {
246				continue
247			}
248			host, _, _ := strings.Cut(side.ref.Location, "/")
249			if !authfilesHold(rec.Authfiles, host, side.creds) {
250				t.Errorf("no authentication file holds the credentials of %s for %s: %+v", side.creds.User, host, rec.Authfiles)
251			}
252		}
253	}
254	
255	// authfilesHold tells whether one of the files, read as a container auth file
256	// ({"auths": {"<host>": {"auth": base64(user:password)}}}), has the credentials
257	// for host (a key may carry a path under the host).
258	func authfilesHold(files []helperAuthfile, host string, c *Credentials) bool {
259		for _, af := range files {
260			var cfg struct {
261				Auths map[string]struct {
262					Auth string `json:"auth"`
263				} `json:"auths"`
264			}
265			if json.Unmarshal([]byte(af.Content), &cfg) != nil {
266				continue
267			}
268			for key, entry := range cfg.Auths {
269				if key != host && !strings.HasPrefix(key, host+"/") {
270					continue
271				}
272				if raw, err := base64.StdEncoding.DecodeString(entry.Auth); err == nil && string(raw) == c.User+":"+c.Password {
273					return true
274				}
275			}
276		}
277		return false
278	}
