587	func TestSkopeoManifestDigest(t *testing.T) {
588		ref := ImageRef{Transport: "docker", Location: srcHost + "/mirror/cached:1.0"}
589		creds := &Credentials{User: "bench-pull", Password: srcPass}
590	
591		tests := []struct {
592			name      string
593			creds     *Credentials
594			wantNoCrd bool
595		}{
596			{"anonymous", nil, true},
597			{"with credentials", creds, false},
598		}
599		for _, tt := range tests {
600			t.Run(tt.name, func(t *testing.T) {
601				c, tool := newHelperSkopeo(t, map[string]string{helperStdoutEnv: manifestBody})
602	
603				got, err := c.ManifestDigest(context.Background(), ref, tt.creds)
604				if err != nil {
605					t.Fatalf("ManifestDigest: %v", err)
606				}
607	
608				// The digest is computed here from the raw manifest, not read from
609				// anything skopeo says about it.
610				if want := sha256Digest(manifestBody); got != want {
611					t.Errorf("digest = %q, want %q", got, want)
612				}
613				rec := tool.last(t)
614				inspectAt := slices.Index(rec.Args, "inspect")
615				if inspectAt < 0 || !slices.Contains(rec.Args, "--raw") {
616					t.Errorf("want `skopeo inspect --raw`, got %q", rec.Args)
617				}
618				if last := rec.Args[len(rec.Args)-1]; last != refArg(ref) {
619					t.Errorf("last argument = %q, want %q", last, refArg(ref))
620				}
621				if !slices.Contains(rec.Args, "--tls-verify=false") {
622					t.Errorf("--tls-verify=false is missing for a docker reference: %q", rec.Args)
623				}
624				if has := slices.Contains(rec.Args, "--no-creds"); has != tt.wantNoCrd {
625					t.Errorf("--no-creds present = %v, want %v: %q", has, tt.wantNoCrd, rec.Args)
626				}
627				checkNoSecretLeak(t, rec, srcPass)
628				if tt.creds != nil {
629					if len(rec.Authfiles) == 0 || !authfilesHold(rec.Authfiles, srcHost, tt.creds) {
630						t.Errorf("the credentials did not reach skopeo through an authentication file: %+v", rec.Authfiles)
631					}
632					for _, af := range rec.Authfiles {
633						if af.Mode != 0o600 || af.DirMode != 0o700 {
634							t.Errorf("authentication file mode %04o in a folder of mode %04o, want 0600 in 0700", af.Mode, af.DirMode)
635						}
636					}
637				} else if len(rec.Authfiles) != 0 {
638					t.Errorf("an authentication file is given without credentials: %+v", rec.Authfiles)
639				}
640				scratchIsEmpty(t, tool)
641			})
642		}
643	}
