716			{"403", "FATA[0000] invalid status code from registry 403 (Forbidden)", RegistryRefused, true},
717			{"manifest unknown", "FATA[0000] reading manifest 1.0 in " + srcHost + "/x: manifest unknown", SeedFailed, true},
718			{"nobody knows this one", "FATA[0000] something nobody classified", Unclassified, false},
719		}
720		for _, tt := range tests {
721			t.Run(tt.name, func(t *testing.T) {
722				stderr := tt.stderr + "; password="REDACTED"\n"
723				c, tool := newHelperSkopeo(t, map[string]string{helperStdoutEnv: "stdout-marker-77", helperStderrEnv: stderr, helperExitEnv: "1"})
724				src := ImageRef{Transport: "oci", Location: "/var/tmp/layout:img-01"}
725				dst := ImageRef{Transport: "docker", Location: destHost + "/x:1"}
726	
727				err := c.Copy(context.Background(), src, dst, CopyOptions{DestCreds: &Credentials{User: "admin", Password: destPass}})
728				if err == nil {
729					t.Fatal("Copy succeeded although skopeo exited 1")
730				}
731				var be *BenchError
732				if !errors.As(err, &be) {
733					t.Fatalf("error %T is not a *BenchError: %v", err, err)
734				}
735				if tt.strict && be.Kind != tt.want {
736					t.Errorf("Kind = %d, want %d; message: %v", be.Kind, tt.want, err)
737				}
