754			{"connection refused, upper case", "Dial TCP: Connection Refused", RegistryUnreachable},
755			{"connection refused behind pinging", "pinging container registry 127.0.0.1:41234: Get \"https://127.0.0.1:41234/v2/\": dial tcp 127.0.0.1:41234: connect: connection refused", RegistryUnreachable},
756			{"no such host", "dial tcp: lookup nexus.invalid on 10.0.0.2:53: no such host", RegistryUnreachable},
