1	package nexusbench
2	
3	import (
4		"encoding/json"
5		"os"
6		"path/filepath"
7		"runtime"
8		"slices"
9		"strconv"
10		"strings"
11		"syscall"
12		"testing"
13		"time"
14	)
15	
16	// The "helper process" pattern of os/exec's own tests, for the two tools the
17	// bench starts (kubectl and skopeo): the tests put a one-line shell shim named
18	// like the tool first on PATH, and the shim re-runs this test binary on
19	// TestHelperProcess, which records what it was given, answers as the test
20	// asked and exits (or hangs, to be killed). PATH holds nothing else, so the
21	// real kubectl and skopeo of the host can never be reached. The shim needs a
22	// POSIX shell.
23	
24	// Environment of the helper, set by installHelperTool.
25	const (
26		helperWantEnv   = "GO_WANT_HELPER_PROCESS" // set by the shim, never by a test
27		helperBinaryEnv = "HELPER_TEST_BINARY"
28		helperToolEnv   = "HELPER_TOOL"
29		helperRecordEnv = "HELPER_RECORD"  // JSON lines, one per run
30		helperPIDEnv    = "HELPER_PIDFILE" // the pid of the last run
31		helperStdoutEnv = "HELPER_STDOUT"
32		helperStderrEnv = "HELPER_STDERR"
33		helperExitEnv   = "HELPER_EXIT"
34		helperHangEnv   = "HELPER_HANG" // "1": print, then wait to be killed
35	)
36	
37	// helperShim is the stand-in binary. The variable is exported by the shim
38	// itself so that only a process started through it ever sees it. The race
39	// detector sleeps one second before a process exits (atexit_sleep_ms), which
40	// would add a second to every run of a stand-in under `mise run test-race`.
41	const helperShim = `#!/bin/sh
42	export GO_WANT_HELPER_PROCESS=1
43	export GORACE="${GORACE:+$GORACE }atexit_sleep_ms=0"
44	exec "$HELPER_TEST_BINARY" -test.run='^TestHelperProcess$' -- "$@"
45	`
46	
47	// helperAuthfile is an authentication file the tool was pointed at, read while
48	// it still existed.
49	type helperAuthfile struct {
50		Flag    string `json:"flag"`
51		Path    string `json:"path"`
52		Mode    uint32 `json:"mode"`
53		DirMode uint32 `json:"dirMode"`
54		Content string `json:"content"`
55	}
56	
57	// helperRecord is what one run of the helper saw.
58	type helperRecord struct {
59		Tool      string           `json:"tool"`
60		Args      []string         `json:"args"`
61		Env       []string         `json:"env"`
62		PID       int              `json:"pid"`
63		Authfiles []helperAuthfile `json:"authfiles"`
64		// PolicyPath and Policy: the --policy file and what it held.
65		PolicyPath string `json:"policyPath"`
66		Policy     string `json:"policy"`
67		// RegistriesConf: CONTAINERS_REGISTRIES_CONF, whether the file existed and
68		// its size.
69		RegistriesConf       string `json:"registriesConf"`
70		RegistriesConfExists bool   `json:"registriesConfExists"`
71		RegistriesConfSize   int64  `json:"registriesConfSize"`
72	}
73	
74	// helperTool is one installed stand-in.
75	type helperTool struct {
76		name      string
77		record    string
78		pidFile   string
79		scratch   string // TMPDIR of the test: where a tool's temporary files go
80		testBytes string
81	}
82	
83	// installHelperTool puts a stand-in for the tool name first, and alone, on PATH
84	// and points TMPDIR at a folder of its own, so a test can tell whether the code
85	// under test left a file behind. env sets the answer of the helper (the
86	// helper*Env names) and anything else the test wants the tool to see.
87	func installHelperTool(t *testing.T, name string, env map[string]string) helperTool {
88		t.Helper()
89		if runtime.GOOS == "windows" {
90			t.Skip("the stand-in tools are POSIX shell scripts")
91		}
92		exe, err := os.Executable()
93		if err != nil {
94			t.Fatalf("locating the test binary: %v", err)
95		}
96		bin, out, scratch := t.TempDir(), t.TempDir(), t.TempDir()
97		if err := os.WriteFile(filepath.Join(bin, name), []byte(helperShim), 0o755); err != nil { //nolint:gosec // an executable shim is the point
98			t.Fatalf("writing the stand-in %s: %v", name, err)
99		}
100		h := helperTool{
101			name:      name,
102			record:    filepath.Join(out, "record.jsonl"),
103			pidFile:   filepath.Join(out, "pid"),
104			scratch:   scratch,
105			testBytes: exe,
106		}
107		t.Setenv("PATH", bin) // nothing else: the real tool cannot be found
108		t.Setenv("TMPDIR", scratch)
109		t.Setenv(helperBinaryEnv, exe)
110		t.Setenv(helperToolEnv, name)
111		t.Setenv(helperRecordEnv, h.record)
112		t.Setenv(helperPIDEnv, h.pidFile)
113		for _, k := range []string{helperStdoutEnv, helperStderrEnv, helperExitEnv, helperHangEnv} {
114			t.Setenv(k, "")
115		}
116		for k, v := range env {
117			t.Setenv(k, v)
118		}
119		return h
120	}
121	
122	// records returns every run of the stand-in, oldest first.
123	func (h helperTool) records(t *testing.T) []helperRecord {
124		t.Helper()
125		raw, err := os.ReadFile(h.record)
126		if os.IsNotExist(err) {
127			return nil
128		}
129		if err != nil {
130			t.Fatalf("reading the record of the stand-in %s: %v", h.name, err)
131		}
132		var out []helperRecord
133		for _, line := range strings.Split(strings.TrimSpace(string(raw)), "\n") {
134			if line == "" {
135				continue
136			}
137			var r helperRecord
138			if err := json.Unmarshal([]byte(line), &r); err != nil {
139				t.Fatalf("decoding a record of the stand-in %s: %v", h.name, err)
140			}
141			out = append(out, r)
142		}
143		return out
144	}
145	
146	// last returns the last run, and fails when the stand-in never ran.
147	func (h helperTool) last(t *testing.T) helperRecord {
148		t.Helper()
149		rs := h.records(t)
150		if len(rs) == 0 {
151			t.Fatalf("the stand-in %s was never run", h.name)
152		}
153		return rs[len(rs)-1]
154	}
155	
156	// neverRan fails when the stand-in was run: the code under test had to refuse
157	// before it started a process.
158	func (h helperTool) neverRan(t *testing.T) {
159		t.Helper()
160		if rs := h.records(t); len(rs) != 0 {
161			t.Errorf("the stand-in %s was run %d time(s) (first: %q), want a refusal before any process", h.name, len(rs), rs[0].Args)
162		}
163	}
164	
165	// pid returns the pid of the last run of a stand-in that is still running.
166	func (h helperTool) pid(t *testing.T) int {
167		t.Helper()
168		raw, err := os.ReadFile(h.pidFile)
169		if err != nil {
170			t.Fatalf("the stand-in %s wrote no pid: %v", h.name, err)
171		}
172		pid, err := strconv.Atoi(strings.TrimSpace(string(raw)))
173		if err != nil {
174			t.Fatalf("the pid file of %s holds %q", h.name, raw)
175		}
176		return pid
177	}
178	
179	// processGone tells whether pid is neither running nor a zombie: signal 0 to a
180	// process that was killed but not waited for still succeeds.
181	func processGone(pid int) bool {
182		p, err := os.FindProcess(pid)
183		if err != nil {
184			return true
185		}
186		return p.Signal(syscall.Signal(0)) != nil
187	}
188	
189	// waitProcessGone polls for processGone: the kill of a cancelled context is
190	// asynchronous.
191	func waitProcessGone(t *testing.T, pid int, within time.Duration) bool {
192		t.Helper()
193		deadline := time.Now().Add(within)
194		for time.Now().Before(deadline) {
195			if processGone(pid) {
196				return true
197			}
198			time.Sleep(10 * time.Millisecond)
199		}
200		return processGone(pid)
201	}
202	
203	// ran tells whether the stand-in has been run at least once. It never fails
204	// the test, so a goroutine may poll it.
205	func (h helperTool) ran() bool {
206		info, err := os.Stat(h.record)
207		return err == nil && info.Size() > 0
208	}
209	
210	// waitRan polls ran; false means the stand-in did not start in time.
211	func (h helperTool) waitRan(within time.Duration) bool {
212		deadline := time.Now().Add(within)
213		for time.Now().Before(deadline) {
214			if h.ran() {
215				return true
216			}
217			time.Sleep(10 * time.Millisecond)
218		}
219		return h.ran()
220	}
221	
222	// flagValue returns the value of a "--flag value" or "--flag=value" argument.
223	func flagValue(args []string, flag string) (string, bool) {
224		for i, a := range args {
225			if a == flag && i+1 < len(args) {
226				return args[i+1], true
227			}
228			if v, ok := strings.CutPrefix(a, flag+"="); ok {
229				return v, true
230			}
231		}
232		return "", false
233	}
234	
235	// TestHelperProcess is not a test: it is the stand-in tool the shim starts.
236	func TestHelperProcess(t *testing.T) {
237		if os.Getenv(helperWantEnv) != "1" {
238			return
239		}
240		args := os.Args
241		if i := slices.Index(args, "--"); i >= 0 {
242			args = args[i+1:]
243		} else {
244			args = nil
245		}
246		rec := helperRecord{Tool: os.Getenv(helperToolEnv), Args: args, Env: os.Environ(), PID: os.Getpid()}
247		rec.readFiles()
248		line, _ := json.Marshal(rec)
249		f, err := os.OpenFile(os.Getenv(helperRecordEnv), os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
250		if err != nil {
251			os.Exit(97)
252		}
253		_, _ = f.Write(append(line, '\n'))
254		_ = f.Close()
255		_ = os.WriteFile(os.Getenv(helperPIDEnv), []byte(strconv.Itoa(os.Getpid())), 0o600)
256	
257		_, _ = os.Stdout.WriteString(os.Getenv(helperStdoutEnv))
258		_, _ = os.Stderr.WriteString(os.Getenv(helperStderrEnv))
259		if os.Getenv(helperHangEnv) == "1" {
260			time.Sleep(time.Hour)
261		}
262		code, _ := strconv.Atoi(os.Getenv(helperExitEnv))
263		os.Exit(code)
264	}
265	
266	// readFiles reads, while they still exist, the files the arguments and the
267	// environment point at.
268	func (r *helperRecord) readFiles() {
269		for _, flag := range []string{"--authfile", "--src-authfile", "--dest-authfile"} {
270			path, ok := flagValue(r.Args, flag)
271			if !ok {
272				continue
273			}
274			af := helperAuthfile{Flag: flag, Path: path}
275			if info, err := os.Stat(path); err == nil {
276				af.Mode = uint32(info.Mode().Perm())
277				if raw, err := os.ReadFile(path); err == nil { //nolint:gosec // a file the code under test named in its own arguments
278					af.Content = string(raw)
279				}
280			}
281			if info, err := os.Stat(filepath.Dir(path)); err == nil {
282				af.DirMode = uint32(info.Mode().Perm())
283			}
284			r.Authfiles = append(r.Authfiles, af)
285		}
286		if path, ok := flagValue(r.Args, "--policy"); ok {
287			r.PolicyPath = path
288			if raw, err := os.ReadFile(path); err == nil { //nolint:gosec // as above
289				r.Policy = string(raw)
290			}
291		}
292		for _, kv := range r.Env {
293			if v, ok := strings.CutPrefix(kv, "CONTAINERS_REGISTRIES_CONF="); ok {
294				r.RegistriesConf = v
295				if info, err := os.Stat(v); err == nil {
296					r.RegistriesConfExists, r.RegistriesConfSize = true, info.Size()
297				}
298			}
299		}
300	}
301	
302	// envOf returns the value of name in an environment list.
303	func envOf(env []string, name string) (string, bool) {
304		for _, kv := range env {
305			if v, ok := strings.CutPrefix(kv, name+"="); ok {
306				return v, true
307			}
308		}
309		return "", false
310	}
