360	// TestWriteLayoutLayerIsAnUncompressedReproducibleTar: the layer is a plain tar
361	// (H-LAYER keeps gzip as the fallback), entries sorted, no date, root owner, and
362	// it holds the image's /bench/<source>/<name>-<tag>.txt.
363	func TestWriteLayoutLayerIsAnUncompressedReproducibleTar(t *testing.T) {
364		dir, images, _ := writeDatasetLayout(t)
365		tree := readTree(t, dir)
366		idx := layoutIndex(t, tree)
367		if len(idx.Manifests) != len(images) {
368			t.Fatalf("%d manifests for %d images", len(idx.Manifests), len(images))
369		}
370	
371		for i, img := range images {
372			t.Run(describeImage(img), func(t *testing.T) {
373				m, layer := layerOf(t, tree, idx, i)
374				if m.Layers[0].MediaType != mediaLayerTar {
375					t.Errorf("layer mediaType = %q, want %q", m.Layers[0].MediaType, mediaLayerTar)
376				}
377				if bytes.HasPrefix(layer, []byte{0x1f, 0x8b}) {
378					t.Error("the layer starts with the gzip magic number")
379				}
380	
381				var names []string
382				var fileModes []int64
383				var files []string
384				tr := tar.NewReader(bytes.NewReader(layer))
385				for {
386					h, err := tr.Next()
387					if errors.Is(err, io.EOF) {
388						break
389					}
390					if err != nil {
391						t.Fatalf("the layer is not a tar archive: %v", err)
392					}
393					names = append(names, h.Name)
394					if h.ModTime.Unix() != 0 || !h.AccessTime.IsZero() || !h.ChangeTime.IsZero() {
395						t.Errorf("%s: carries a date (mtime %v, atime %v, ctime %v)", h.Name, h.ModTime, h.AccessTime, h.ChangeTime)
396					}
397					if h.Uid != 0 || h.Gid != 0 {
398						t.Errorf("%s: owner %d:%d, want 0:0", h.Name, h.Uid, h.Gid)
399					}
400					if h.Uname != "" || h.Gname != "" {
401						t.Errorf("%s: owner names %q:%q, want none", h.Name, h.Uname, h.Gname)
402					}
403					if h.Typeflag == tar.TypeReg {
404						fileModes = append(fileModes, h.Mode)
405						files = append(files, strings.TrimPrefix(h.Name, "/"))
406					}
407				}
408				if !sort.StringsAreSorted(names) {
409					t.Errorf("entries are not sorted: %v", names)
410				}
411				for _, mode := range fileModes {
412					if mode != fileModes[0] {
413						t.Errorf("regular files have different modes: %v", fileModes)
414						break
415					}
416				}
417	
418				// One file under /bench/<source>/, named after the image.
419				prefix := "bench/" + sourceOf(img.Location) + "/"
420				var found []string
421				for _, f := range files {
422					if strings.HasPrefix(f, prefix) {
423						found = append(found, f)
424					}
425				}
426				if len(found) != 1 {
427					t.Fatalf("regular files under /%s: %v, want exactly one (all files: %v)", prefix, found, files)
428				}
429				if !strings.HasSuffix(found[0], "-"+img.Tag+".txt") {
430					t.Errorf("%s does not end with -%s.txt", found[0], img.Tag)
431				}
432				rest := strings.TrimPrefix(found[0], prefix)
433				if !strings.Contains(rest, img.Name) && !strings.Contains(rest, strings.ReplaceAll(img.Name, "/", "-")) {
434					t.Errorf("%s does not name the image %s", found[0], img.Name)
435				}
436			})
437		}
438	}
